function escapeString(s) {
    return s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function formatQuestion(q, choices, correct) {
    const choicesStr = choices.map(c => `"${escapeString(c)}"`).join(', ');
    return `                {
                    question: "${escapeString(q)}",
                    choices: [${choicesStr}],
                    correct: "${escapeString(correct)}",
                }`;
}

let total = 0;
const difficultyKeys = Object.keys(topics);
const difficultyBlocks = difficultyKeys.map(difficulty => {
    const topicMap = topics[difficulty];
    const topicKeys = Object.keys(topicMap);
    const topicBlocks = topicKeys.map(topic => {
        const qs = topicMap[topic];
        if (qs.length !== 20) throw new Error(`${topic} has ${qs.length} questions, expected 20`);
        total += qs.length;
        const items = qs.map(([q, c, a]) => formatQuestion(q, c, a)).join(',\n');
        return `            "${topic}": [\n${items}\n            ]`;
    });
    return `        "${difficulty}": {\n${topicBlocks.join(',\n')}\n        }`;
});

const content = `// Java practice topics extension for CodeQuiz
if (typeof quizData !== "undefined" && quizData.Java) {
    quizData.Java.practiceTopics = {
${difficultyBlocks.join(',\n')}
    };
}
`;

const outPath = path.join(__dirname, 'java-practice-data.js');
fs.writeFileSync(outPath, content, 'utf8');
console.log('Written:', outPath);
console.log('Difficulties:', difficultyKeys.length);
console.log('Questions:', total);
console.log('Size bytes:', fs.statSync(outPath).size);
